/* =====================================================
   published.js : the calm ending. Add it to home.html (after the other scripts), plus css/published.css.
   Once a review has been accepted (review-write.html), the visitor lands on the main page and their review is already published at the top of it,
   written onto the graphic images/review-published.png. When they scroll to the end of the graphic the whole screen glitches out and three lines appear:
       you have completed your purpose / please leave now / thank you for being real
   (no sound, no typing, nothing moving), and a few seconds later the tab closes itself.
   (Browsers only allow a tab to close itself if a script opened it. If it will not, the page goes blank (about:blank).)
   Testing: open home.html?published=1 to see it without having written a review.
   ===================================================== */
(function () {
  const KEY = 'realStuf.review';
  const GRAPHIC = 'images/review-published.png';
  const SAMPLE = 'love this shirt!! so real. so genuine. i could tell the moment i put it on. 5 stars, would be real again.';
  const LINES = ['you have completed your purpose', 'please leave now', 'thank you for being real'];
  const END_HOLD = 900;                 // ms they have to stay at the end of the review
  const GLITCH_MS = 1700;               // how long the glitch lasts
  const SCREEN_MS = 3200;               // how long each sentence stays on its own screen
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

  let S = {}; try { S = JSON.parse(sessionStorage.getItem(KEY) || '{}'); } catch (e) {}
  const test = /[?&]published=1/.test(location.search);
  if (!((S.done && S.review) || test)) return;                         // only after a review was accepted
  const review = (S.review || '').trim() || SAMPLE;

  /* ---------- the published review: an old-computer window (the same frame and scrollbar as the other review windows, css/reviews.css) ---------- */
  const FRAME = 'images/review-frame.png', FW = 706, FH = 472;
  const OPEN_AFTER = 2000;                                            // ms on the main page before the review window opens
  const LOAD_FOR = 2000;                                              // ms the window "loads" before the review shows
  const SCALE_UP = 1.35;                                              // on a big screen the window may grow this much
  const layer = document.createElement('div'); layer.className = 'rv-layer pub-layer';
  const dim = document.createElement('div'); dim.className = 'pub-dim';
  const win = document.createElement('div'); win.className = 'rv-win';
  win.innerHTML =
    '<img class="rv-frame" alt="" src="' + FRAME + '">' +
    '<div class="rv-body"><div class="rv-load"><b>' + [0, 1, 2, 3, 4, 5, 6, 7].map(function (k) { const a = k * Math.PI / 4; return '<i style="left:' + (23 + 23 * Math.sin(a)) + 'px;top:' + (23 - 23 * Math.cos(a)) + 'px;animation-delay:' + (k * .1) + 's"></i>'; }).join('') + '</b>loading review...</div>' +
    '<div class="rv-scroll"><div class="rv-page"><img alt="NEW REVIEW! A new review from a beloved customer! 5 stars" src="' + GRAPHIC + '"><p class="pub-text"></p></div></div></div>' +
    '<div class="rv-bar"><button class="rv-up" type="button" aria-label="Scroll up"></button><div class="rv-track"><div class="rv-thumb"></div></div><button class="rv-dn" type="button" aria-label="Scroll down"></button></div>';
  layer.appendChild(win); document.body.appendChild(dim); document.body.appendChild(layer);
  layer.style.display = dim.style.display = 'none';                   // nothing yet: the main page sits there for OPEN_AFTER first
  function place() {                                                  // centred, scaled to fit the screen
    const vw = innerWidth, vh = innerHeight, sc = Math.min(SCALE_UP, (vw - 16) / FW, (vh - 90) / FH), w = FW * sc, h = FH * sc;
    win.style.left = Math.max(8, (vw - w) / 2) + 'px'; win.style.top = Math.max(50, (vh - h) / 2) + 'px'; win.style.transform = 'scale(' + sc + ')'; win.dataset.s = sc;
  }
  place(); addEventListener('resize', function () { place(); sync(); });

  const sc = win.querySelector('.rv-scroll'), thumb = win.querySelector('.rv-thumb'), track = win.querySelector('.rv-track'), textEl = win.querySelector('.pub-text');
  textEl.textContent = review;
  function fit() {                                                    // a long review gets smaller letters until it fits its space
    let size = 3.5; textEl.style.fontSize = size + 'cqw';
    while (textEl.scrollHeight > textEl.clientHeight + 1 && size > 1.5) { size -= .1; textEl.style.fontSize = size + 'cqw'; }
  }
  addEventListener('load', fit); if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);
  function sync() {                                                   // the scrollbar handle follows the scrolling
    const max = sc.scrollHeight - sc.clientHeight, h = track.clientHeight;
    if (max <= 0 || !h) { thumb.style.display = 'none'; return; }
    thumb.style.display = ''; const th = Math.max(30, h * sc.clientHeight / sc.scrollHeight);
    thumb.style.height = th + 'px'; thumb.style.top = (sc.scrollTop / max) * (h - th) + 'px';
  }
  [['.rv-up', -1], ['.rv-dn', 1]].forEach(function (a) {             // the arrows scroll while held
    const b = win.querySelector(a[0]); let t;
    b.addEventListener('pointerdown', function (e) { e.preventDefault(); const go = function () { sc.scrollTop += a[1] * 48; }; go(); t = setInterval(go, 70); });
    ['pointerup', 'pointerleave', 'pointercancel'].forEach(function (ev) { b.addEventListener(ev, function () { clearInterval(t); }); });
  });
  thumb.addEventListener('pointerdown', function (e) {                // the handle drags
    e.preventDefault(); thumb.setPointerCapture(e.pointerId);
    const k = +win.dataset.s || 1, y0 = e.clientY, top0 = sc.scrollTop, room = track.clientHeight - thumb.offsetHeight, max = sc.scrollHeight - sc.clientHeight;
    const move = function (m) { sc.scrollTop = top0 + ((m.clientY - y0) / k) / (room || 1) * max; };
    const up = function () { thumb.removeEventListener('pointermove', move); thumb.removeEventListener('pointerup', up); };
    thumb.addEventListener('pointermove', move); thumb.addEventListener('pointerup', up);
  });
  track.addEventListener('pointerdown', function (e) { if (e.target !== track) return; const r = thumb.getBoundingClientRect(); sc.scrollTop += (e.clientY < r.top ? -1 : 1) * sc.clientHeight * .9; });
  win.querySelector('.rv-page img').addEventListener('load', sync);

  /* ---------- reaching the end of the graphic ---------- */
  let ready = false, fired = false, endTimer = 0;
  setTimeout(function () {                                            // the window opens, like the others: the same thud
    layer.style.display = dim.style.display = '';
    document.documentElement.style.overflow = 'hidden'; document.body.style.overflow = 'hidden';       // the page behind stays still while the window is open
    place(); fit(); window.sfx && (sfx('unlock'), sfx('thud'));
    setTimeout(function () { win.classList.add('ready'); ready = true; sync(); }, LOAD_FOR);
  }, OPEN_AFTER);
  sc.addEventListener('scroll', function () {
    sync();
    if (!ready || fired) return;
    const atEnd = sc.scrollTop >= sc.scrollHeight - sc.clientHeight - 3;
    if (atEnd && !endTimer) endTimer = setTimeout(function () { fired = true; theEnd(); }, END_HOLD);
    if (!atEnd && endTimer) { clearTimeout(endTimer); endTimer = 0; }                   // they scrolled back up: not yet
  });

  /* ---------- the end ---------- */
  function theEnd() {
    window.sfx && sfx('hum', 0);
    document.documentElement.classList.add('pub-glitching'); document.body.classList.add('pub-glitching');
    const root = document.body, bars = document.createElement('div'); bars.className = 'pub-bars'; document.body.appendChild(bars);
    const rnd = function (a, b) { return a + Math.random() * (b - a); };
    const t0 = performance.now();
    (function frame() {
      const t = performance.now() - t0, k = Math.min(1, t / GLITCH_MS);
      if (t >= GLITCH_MS || reduce) { root.style.cssText = ''; bars.remove(); showFinal(); return; }
      const hard = Math.random() < .4 + k * .4;                       // it gets worse as it goes
      root.style.transform = hard ? 'translate(' + rnd(-60, 60) * k + 'px,' + rnd(-8, 8) + 'px) skewX(' + rnd(-14, 14) * k + 'deg)' : 'none';
      root.style.clipPath = Math.random() < .5 ? 'inset(' + rnd(0, 50) + '% 0 ' + rnd(0, 40) + '% 0)' : 'none';
      root.style.filter = 'hue-rotate(' + rnd(-90, 90) + 'deg) contrast(' + (1 + k) + ') saturate(' + (1 + k * 2) + ')';
      bars.innerHTML = '';
      const n = Math.floor(2 + k * 7);
      for (let i = 0; i < n; i++) { const b = document.createElement('i'); b.style.cssText = 'top:' + rnd(0, 100) + '%;height:' + rnd(.4, 6) + '%;opacity:' + rnd(.3, .9) + ';background:' + (Math.random() < .5 ? '#0ff' : '#f0f'); bars.appendChild(b); }
      if (hard && window.sfx) sfx('static');
      setTimeout(frame, rnd(40, 110));
    })();
  }
  function showFinal() {
    document.documentElement.classList.remove('pub-glitching'); document.body.classList.remove('pub-glitching');
    document.title = 'real.';
    document.body.style.overflow = 'hidden'; document.documentElement.style.overflow = 'hidden';
    layer.remove(); dim.remove();
    const f = document.createElement('div'); f.className = 'pub-final'; document.body.appendChild(f);   // the empty pale screen
    let i = 0;
    (function next() {
      if (i >= LINES.length) {                                        // the last sentence has had its time: the tab closes
        window.close();                                               // only works for a tab a script opened
        setTimeout(function () { f.style.background = '#fff'; f.innerHTML = ''; location.replace('about:blank'); }, 400);
        return;
      }
      f.innerHTML = '<p>' + LINES[i++] + '</p>';                      // one sentence alone on the screen, and straight on to the next
      setTimeout(next, SCREEN_MS);
    })();
  }
})();
